"""Tactical motion comic with a pre-battle introduction and engine HP snapshots."""
from pathlib import Path
import json,math,os,re,sys,subprocess
from functools import lru_cache
import numpy as np
import soundfile as sf
from PIL import Image,ImageDraw,ImageFont,ImageOps
BASE=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(BASE/'examples/tactical_v1'))
from render_support import speech_engine,phonemes
ROOT=Path(sys.argv[1]).resolve()
W,H,FPS,SR=720,1280,24,24000
@lru_cache(maxsize=20)
def font(n):return ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf',n)
def voice():
 c=json.loads((ROOT/'script.json').read_text());engine=speech_engine();pieces=[];start=0
 for i,s in enumerate(c['segments']):
  s['index']=i;s['start']=start;s['captions']=[];cursor=0;parts=[]
  for phrase in re.split(r'(?<=[.!?])\s+',s['text']):
   a,sr=engine.create(phonemes(phrase,engine),voice='am_michael',speed=1.12,lang='en-us',is_phonemes=True,sentence_pause=.14,clause_pause=.08)
   assert sr==SR
   a=np.concatenate([a,np.zeros(round(.12*SR),np.float32)])
   s['captions'].append(dict(text=phrase,start=cursor,duration=len(a)/SR));cursor+=len(a)/SR;parts.append(a)
  a=np.concatenate(parts+[np.zeros(round(.18*SR),np.float32)])
  frames=math.ceil(len(a)/SR*FPS);a=np.pad(a,(0,round(frames/FPS*SR)-len(a)))
  s['duration']=len(a)/SR;start+=s['duration'];pieces.append(a)
 c['duration']=start;c['voice']={'engine':'Kokoro ONNX','voice':'am_michael','speed':1.12}
 sf.write(ROOT/'narration.wav',np.concatenate(pieces),SR)
 (ROOT/'story.json').write_text(json.dumps(c,indent=2));print('NARRATION',ROOT.name,round(start,2),flush=True)
 if not 45<=start<=75:raise RuntimeError('Duration outside target; revise narration')
def wrap(d,text,x,y,width,size,fill='white',center=False):
 f=font(size);lines=[];line=''
 for w in text.split():
  trial=(line+' '+w).strip()
  if d.textlength(trial,font=f)>width and line:lines.append(line);line=w
  else:line=trial
 if line:lines.append(line)
 for line in lines:
  xx=x+(width-d.textlength(line,font=f))/2 if center else x
  d.text((xx,y),line,font=f,fill=fill,stroke_width=1,stroke_fill='#080D19');y+=size+10
 return y
def hp(d,p,hp,x,color):
 pct=100*max(0,hp)/p['max_hp'];d.text((x,49),p['name'].upper(),font=font(22),fill='white')
 d.text((x+230,49),str(round(pct))+'%',font=font(21),fill='white')
 d.rounded_rectangle((x,82,x+290,97),radius=6,fill='#354052')
 if pct>0:d.rounded_rectangle((x,82,x+max(1,round(290*pct/100)),97),radius=6,fill=color)
 d.text((x,105),' / '.join(p['types']).upper(),font=font(14),fill='#D3DAE6')
 d.text((x,124),f"{round(hp)} / {p['max_hp']} HP",font=font(13),fill='#D3DAE6')
OVERLAY=Image.new('RGBA',(W,H));od=ImageDraw.Draw(OVERLAY);od.rectangle((0,0,W,147),fill=(6,11,21,241))
for yy in range(930,H):od.line((0,yy,W,yy),fill=(6,11,21,round(min(242,(yy-930)*1.65))))
def frame(c,s,art,t,b):
 p=t/s['duration'];accent='#FFD777' if s['kind'] in ['intro','result'] else '#A8EEFF'
 zoom=1.012+.025*p;scaled=art.resize((round(W*zoom),round(1080*zoom)),Image.Resampling.BICUBIC)
 im=Image.new('RGB',(W,H),'#080D19');im.paste(scaled,((W-scaled.width)//2,145-(scaled.height-1080)//2))
 im=Image.alpha_composite(im.convert('RGBA'),OVERLAY);d=ImageDraw.Draw(im)
 d.text((30,14),' vs '.join(c['pair']).upper(),font=font(22),fill='white')
 if s['kind']=='intro':before=after=b['initial'];label='MATCHUP'
 elif s['kind']=='result':before=after=b['turns'][-1]['after'];label='RESULT'
 else:
  e=b['events'][s['event_index']];before=e['before'];after=e['after'];label=f"ROUND {e['turn']} / {len(b['turns'])}"
 mix=max(0,min(1,(t-.35)/.8)) if s['kind']=='move' else 0
 for k,(a,z) in enumerate(zip(before,after)):hp(d,z,a['hp']+(z['hp']-a['hp'])*mix,30 if k==0 else 392,['#6BD6FA','#8EEC79'][k])
 d.rounded_rectangle((30,167,245,207),radius=8,fill='#080D19',outline=accent,width=2);d.text((44,176),label,font=font(20),fill='white')
 if s['kind']=='intro':
  d.rounded_rectangle((30,227,690,279),radius=8,fill='#10182A');wrap(d,' vs '.join(c['pair']),45,237,630,27,accent,True)
 if s['kind']=='result':
  loser=next(x for x in c['pair'] if x!=b['winner'])
  d.rounded_rectangle((30,227,630,283),radius=9,fill='#211B0C',outline=accent,width=2);d.text((45,241),'WINNER: '+b['winner'].upper(),font=font(27),fill=accent)
  d.rounded_rectangle((30,300,630,347),radius=9,fill='#10182A');d.text((45,312),loser.upper()+': FAINTED',font=font(23),fill='white')
 wrap(d,s['title'],30,942,660,30,accent)
 wrap(d,s['note'],30,991,660,19,accent)
 chosen=s['captions'][-1]
 for cap in s['captions']:
  if cap['start']<=t<cap['start']+cap['duration']:chosen=cap;break
 words=chosen['text'].split();chunks=[' '.join(words[k:k+6]) for k in range(0,len(words),6)]
 q=max(0,min(.999,(t-chosen['start'])/chosen['duration']));wrap(d,chunks[min(len(chunks)-1,int(q*len(chunks)))],36,1053,648,35,'white',True)
 d.rectangle((30,1200,690,1204),fill='#334057');d.rectangle((30,1200,30+660*(s['start']+t)/c['duration'],1204),fill=accent)
 d.text((30,1226),'LV100  /  GEN9  /  NO ITEMS',font=font(17),fill='#D7DFEC');d.text((30,1253),'PLANNED CHOICES  /  SIMULATED DAMAGE',font=font(14),fill='#AAB7CC')
 return im.convert('RGB')
def render():
 c=json.loads((ROOT/'story.json').read_text());b=json.loads((ROOT/'battle.json').read_text());images=json.loads((ROOT/'images.json').read_text());assert len([s for s in c['segments'] if s['kind']=='move'])==len(b['events'])
 cmd=['ffmpeg','-v','error','-y','-f','rawvideo','-pix_fmt','rgb24','-s',f'{W}x{H}','-r',str(FPS),'-i','pipe:0','-i',str(ROOT/'narration.wav'),'-c:v','libx264','-preset','veryfast','-crf','20','-pix_fmt','yuv420p','-c:a','aac','-b:a','160k','-af','loudnorm=I=-16:TP=-1.5:LRA=9','-ar','48000','-movflags','+faststart','-shortest',str(ROOT/c['output'])]
 proc=subprocess.Popen(cmd,stdin=subprocess.PIPE);arts={k:ImageOps.fit(Image.open(ROOT/v).convert('RGB'),(W,1080),Image.Resampling.LANCZOS) for k,v in images.items()}
 for s in c['segments']:
  for n in range(round(s['duration']*FPS)):
   im=frame(c,s,arts[s['image_key']],n/FPS,b);proc.stdin.write(im.tobytes())
   if n==min(round(s['duration']*FPS)-1,round(1.5*FPS)):im.save(ROOT/f"review-{s['index']:02d}.jpg",quality=92)
  print('SCENE',ROOT.name,s['index'],flush=True)
 proc.stdin.close();assert proc.wait()==0;print('RENDERED',ROOT/c['output'],flush=True)
if '--render' in sys.argv:render()
else:voice()

