const fs=require('fs'),path=require('path');
const {Battle,Dex,TeamValidator}=require('pokemon-showdown');
const cfg=JSON.parse(fs.readFileSync(process.argv[2]));const format='gen9nationaldex';
const validator=new TeamValidator(format);
for(const set of cfg.builds){const errors=validator.validateTeam([structuredClone(set)]);if(errors?.length)throw Error(errors.join('\n'));}
const catalogue=JSON.parse(fs.readFileSync(path.join(__dirname,'../pokemon/tactical_moves.json'))).pokemon;
for(const b of cfg.builds){const c=catalogue.find(x=>x.species===b.species);if(!c||b.moves.length!==4||b.moves.some(m=>!c.moves.some(x=>x.name===m)))throw Error('Invalid equipped catalogue moves');}
const seed=Array.from({length:4},(_,i)=>require('crypto').createHash('sha256').update(cfg.simulation_key).digest().readUInt16BE(i*2));
const battle=new Battle({formatid:format,seed,send:()=>{}});const events=[];let current=null;
const snap=p=>({name:p.name,hp:p.hp,max_hp:p.maxhp,types:p.getTypes(),status:p.status,boosts:{...p.boosts},speed:p.getStat('spe'),stats:{atk:p.getStat('atk',false,true),def:p.getStat('def',false,true),spa:p.getStat('spa',false,true),spd:p.getStat('spd',false,true)}});
const addMove=battle.addMove;battle.addMove=function(...args){if(args[0]==='move'){current={turn:this.turn,actor:args[1].name,move:args[2],before:this.sides.map(s=>snap(s.active[0])),damage:[]};events.push(current);}return addMove.apply(this,args);};
const add=battle.add;battle.add=function(...args){if(args[0]==='-damage'&&current&&args[1]?.side){const p=args[1];current.damage.push({target:p.name,hp_after:p.hp,max_hp:p.maxhp});}if(args[0]==='-miss'&&current)current.missed=true;return add.apply(this,args);};
battle.setPlayer('p1',{name:cfg.builds[0].species,team:[cfg.builds[0]]});battle.setPlayer('p2',{name:cfg.builds[1].species,team:[cfg.builds[1]]});if(battle.requestState==='teampreview')battle.makeChoices('team 1','team 1');
const initial=battle.sides.map(s=>snap(s.active[0]));const turns=[];
for(let i=0;i<cfg.plans.length&&!battle.ended;i++){const from=battle.log.length;const choices=cfg.plans[i].map((m,s)=>'move '+(battle.sides[s].active[0].moveSlots.findIndex(x=>x.id===Dex.moves.get(m).id)+1));battle.makeChoices(...choices);turns.push({turn:i+1,planned:cfg.plans[i],after:battle.sides.map(s=>snap(s.active[0])),log:battle.log.slice(from)});if(battle.log.some(x=>x.startsWith('|error|')))throw Error('Battle engine error');}
for(let i=0;i<events.length;i++){const e=events[i];e.after=i+1<events.length?events[i+1].before:turns.at(-1).after;const hp=Object.fromEntries(e.before.map(p=>[p.name,p.hp]));const seen=new Set();e.damage=e.damage.filter(d=>{const k=d.target+':'+d.hp_after;if(seen.has(k))return false;seen.add(k);return true;});for(const d of e.damage){d.hp_lost=hp[d.target]-d.hp_after;hp[d.target]=d.hp_after;d.percent_max_hp=+(100*d.hp_lost/d.max_hp).toFixed(2);}e.damage_total=e.damage.reduce((s,d)=>s+d.hp_lost,0);const m=Dex.moves.get(e.move);e.move_info={type:m.type,category:m.category,accuracy:m.accuracy,priority:m.priority,base_power:m.basePower};}
const out={schema:2,format,seed,simulation_key:cfg.simulation_key,builds:cfg.builds,moveBanks:cfg.builds.map(b=>catalogue.find(x=>x.species===b.species)),initial,events,turns,ended:battle.ended,winner:battle.winner,log:battle.log,simulator_version:require('pokemon-showdown/package.json').version,policy:cfg.policy};fs.writeFileSync(path.join(path.dirname(process.argv[2]),'battle.json'),JSON.stringify(out,null,2));console.log(JSON.stringify({seed,initial,events:events.map(e=>({turn:e.turn,actor:e.actor,move:e.move,damage:e.damage,missed:e.missed,after:e.after.map(p=>({name:p.name,hp:p.hp,boosts:p.boosts,status:p.status}))})),winner:out.winner,ended:out.ended,turns:turns.length,log:battle.log},null,2));battle.destroy();
